import{describe,it,expect}from"vitest";import{WETLANDS_DATA}from"../../frontend/wetlands/wetlands-data.js";import{resolve}from"path";import{readFileSync}from"fs";describe("Wetlands of India Explorer Landing Page",()=>{it("should have a comprehensive dataset for Wetlands of India",()=>{expect(WETLANDS_DATA).toBeDefined(),expect(Array.isArray(WETLANDS_DATA.stats)).toBe(!0),expect(WETLANDS_DATA.stats.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(WETLANDS_DATA.types)).toBe(!0),expect(WETLANDS_DATA.types).toContain("Lagoon"),expect(WETLANDS_DATA.types).toContain("Lake"),expect(WETLANDS_DATA.types).toContain("Mangrove"),expect(Array.isArray(WETLANDS_DATA.wetlands)).toBe(!0),expect(WETLANDS_DATA.wetlands.length).toBeGreaterThanOrEqual(5)}),it("every wetland entry should have required card properties",()=>{WETLANDS_DATA.wetlands.forEach(e=>{expect(e.id).toBeDefined(),expect(e.name).toBeDefined(),expect(e.state).toBeDefined(),expect(e.type).toBeDefined(),expect(e.shortDesc).toBeDefined(),expect(e.image).toBeDefined(),expect(e.exploreUrl).toBeDefined()})}),it("should be indexed in search-index.js",()=>{const e=resolve(__dirname,"../../search-index.js"),t=readFileSync(e,"utf-8");expect(t).toContain("frontend/wetlands/index.html"),expect(t).toContain("Wetlands of India Explorer")})});